import{_ as o,l as t,o as e,c as l,v as n,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"宏观审慎政策","description":"","frontmatter":{"title":"宏观审慎政策","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/macroprudential.md","filePath":"econ/macroprudential.md","lastUpdated":1789023840000}'),E={name:"econ/macroprudential.md"};function h(m,a,_,u,A,B){const i=t("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="宏观审慎政策" tabindex="-1">宏观审慎政策 <a class="header-anchor" href="#宏观审慎政策" aria-label="Permalink to &quot;宏观审慎政策&quot;">​</a></h1><div class="epigraph"><p>对杠杆的约束是总量状态上的政策，目标是外部性：火线出售与中介净值的价格影响未进入私人一阶条件。</p><footer>—— Bianchi and Mendoza；Jeanne and Korinek 的杠杆外部性；Basel III 的逆周期缓冲作为制度对照</footer></div><p><a href="/econ/eggertsson-krugman">上一课</a>的 \\(\\bar b\\) 突然下降是灾难。本课缺口是<strong>事前</strong>把 \\(\\bar b\\) 或银行 \\(\\phi\\) 当成工具：宏观审慎。不重推 ZLB 乘数，不写巴塞尔每一条会计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>KM/GK/住房 LTV 里，私人借款人与银行不内化 \\(q\\) 与净值的价格效应。繁荣时过度杠杆，崩溃时放大。审慎：逆周期 LTV、资本缓冲、保证金。与货币政策分工：利率是粗工具，同时管通胀与杠杆会冲突（Tinbergen）。缺口是给「金融稳定政策」一条外部性语言，而不是把所有稳定都交给泰勒规则。</p><p><span class="marginnote">Jeanne and Korinek；Bianchi, <em>AER</em> 2011 过度借贷。Farhi and Werning 的宏观审慎与货币。Galati and Moessner 综述。Basel III CCyB 是制度，不是本课推导出来的最优税率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>福利：比较竞争均衡与计划者，得到对债务的 Pigou 税或数量限制。定量：在 Iacoviello 或 GK 里对 LTV、资本要求做 Ramsey 或简单规则。与 ZLB：事前审慎减少事后陷阱的概率，与事后财政是互补。开放：资本流入税是同一外部性的跨境版（后课全球金融周期）。</p>',8)),(e(),s(c,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXT%5B%22%E6%9D%A0%E6%9D%86%E5%A4%96%E9%83%A8%E6%80%A7%22%5D%20--%3E%20TOOL%5B%22LTV%20%2F%20%E8%B5%84%E6%9C%AC%20%2F%20%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20TOOL%20--%3E%20LEV%5B%22%E7%B9%81%E8%8D%A3%E6%9C%9F%E6%9D%A0%E6%9D%86%22%5D%0A%20%20MP%5B%22%E5%88%A9%E7%8E%87%22%5D%20--%3E%20BOTH%5B%22%E9%80%9A%E8%83%80%E4%B8%8E%E6%9D%A0%E6%9D%86%E5%86%B2%E7%AA%81%22%5D%0A%20%20TOOL%20--%3E%20DIV%5B%22%E5%B7%A5%E5%85%B7%E5%88%86%E5%B7%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>识别：审慎工具的宏观 IRF 短、内生性强，叙事与跨国差异（英国 FPC、香港 LTV）比 SVAR 更常用。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把约束当政策而非当技术。过紧：正常时期投资与住房服务损失；过松：崩溃概率。偶尔绑定使最优政策本身状态依存：松约束世界里审慎几乎无成本也无收益。预期：若审慎被预见为「繁荣必收」，可抑制诊断性房价过冲。</p><p>与 HANK：LTV 主要绑中产住房借款人，分配效应明显，不是代表性福利能概括。</p><p><span class="marginnote">本课不把微观审慎（单家银行风险）与宏观审慎（周期与系统）混成一词。前者已有资本监管课接口。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定 CCyB 的基点。不写全部宏观审慎工具箱清单。影子银行会绕开（后课）。货币主导与财政主导会限制谁有工具。下一课把同一外部性放到跨境资本流。</p><p>后课默认：宏观审慎针对杠杆外部性，与利率分工。下一课：全球金融周期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>杠杆有价格外部性，审慎是 Pigou 或数量工具。</li><li>与货币政策分工，因工具与目标数量。</li><li>过紧有稳态成本；状态依存是关键。</li><li>出处：Bianchi；Jeanne and Korinek；Farhi and Werning。</li></ul>',10))])}const D=o(E,[["render",h]]);export{f as __pageData,D as default};
